import{_ as e,o as t,c as _,a3 as p}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-081.BcLginZy.jpg",m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/86-住在山手圈内的中流阶层.md","filePath":"books/xialiu-shehui/86-住在山手圈内的中流阶层.md","lastUpdated":1794732511000}'),s={name:"books/xialiu-shehui/86-住在山手圈内的中流阶层.md"};function i(r,a,n,l,c,d){return t(),_("div",null,[...a[0]||(a[0]=[p('<h2 id="住在山手圈内的中流阶层" tabindex="-1">住在山手圈内的中流阶层 <a class="header-anchor" href="#住在山手圈内的中流阶层" aria-label="Permalink to &quot;住在山手圈内的中流阶层&quot;">​</a></h2><p>所谓山手圈、“下只角”，并不单指地形，同时也表示住在那里的人们的阶层和生活状态。</p><p>说到山手圈，从字面上来看，就是指山或者丘陵地带。山丘的上面居住着处于支配地位的阶层。无论哪个国家，上流阶层都喜欢住在高的地方，比如山上或是丘陵之上，在美国有比弗利山庄，在巴黎则有蒙马特高地。如果没有山丘，那就建造一座人工山——超高层的住宅楼，住在最上层，领略身居高处高高在上的感觉，东京的“六本木山”便是这样诞生的。</p><p>在东京，这样的丘陵地带从皇室所在地的西侧延伸出去，因此直到现在，依然保持着上流阶层或中流阶层住在西侧、普通平民百姓住在东侧的格局。西侧是山手圈，东侧便是所谓的“下只角”。</p><p>军人、学者、医生大体上也都住在山手圈，日本文豪森鸥外和夏目漱石就都住在本乡。</p><p>图8-2是东京帝国大学教授的住所分布图。在明治二十年（1887年），东京帝大的教授不仅住在大学周围，也住在所谓的“下只角”。到了大正十二年（1923年），中野、中目黑等山手线西侧一带的住宅区逐渐扩大，至昭和十八年（1943年），更是一下子向西扩展到了荻窪、吉祥寺、三鹰、明大前、成城、自由之丘、田园调布，第三山手圈成了东京帝国大学教授的聚居地，并且也成为众多中流工薪阶层居住的地方。山手圈逐渐呈现出大众化的趋势。</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>图8-2　东京帝国大学教授住宅分布图1887年（明治二十年）右上1923年（大正十二年）左上1943年（昭和十八年）下（资料出处：高田宏等《从居住者分布看“山手圈”的扩大》，收录于岩渊润子、HighLife研究会、山手研究会合编《东京的山手大研究》）</p><p>上世纪70年代至80年代，作为日本中流社会论的重要人物之一，村上泰亮在《新中间大众的时代》中阐述道，所谓中流阶层，就是在经济方面“谈不上富有，但拥有能维持一定生活水准的收入和财产”，在政治方面“拥有选举权”、“在行政机构、民营企业、地方社区担当某方面管理职务的阶层”，他们是产业社会的运营管理所不可或缺的提供和传递信息及知识的专门阶层，在文化方面，他们“接受过高等教育”“懂得勤勉、节约、尊重家人，具有计划性、效率性和责任感等适应产业化的特质”。换句话说，“所谓中流阶层，无非就是代表资本主义实质文化的领导阶层”“这个定义不仅适用于日本，而且适用于所有的产业社会”。</p><p>村上泰亮还写道，说起这个中流阶层，如果以日本为例，相当于战前东京的“山手阶级”。构成山手阶级的主要阶层包括官吏、公司职员、教师、专业技术人员、医生、小企业主等，他们毕业于大学或是专科学校，平时有读书看报的习惯，住着有西式客厅的住宅，雇着女佣，上下班穿着西装，言谈举止颇有教养，还孕育出一种被称作“山手式语言”的说话方式。这正是一般人对于住在第二山手圈和第三山手圈的中流阶层的印象。</p><p>然而“二战”之后，山手圈逐渐变得大众化了。多摩丘陵被铲平开发成新的居住地，建设起了许多住宅。伴随着经济的发展，越来越多的日本国民进入中流阶层，他们购置家电、买车、买房，每个人都切实感到自己已经成了中流阶层的一员。如果有谁在东京郊外买房子，那么自己和别人都会觉得他确实属于中流阶层。</p>',11)])])}const u=e(s,[["render",i]]);export{m as __pageData,u as default};
